import { officeStage } from './office-stage.js';

const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = (v = '') => String(v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const api = async (path, options = {}) => {
  const init = { ...options, headers: { 'content-type': 'application/json', ...(options.headers || {}) } };
  if (init.body && typeof init.body !== 'string') init.body = JSON.stringify(init.body);
  const res = await fetch(path, init);
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error || `HTTP ${res.status}`);
  return data;
};

const viewInfo = {
  workspace: ['GIT WORKSPACE', '오피스 관리'],
  office: ['TODAY\'S OFFICE', '오피스'], board: ['WORKFLOW', '작업 보드'],
  history: ['ARCHIVE', '실행 기록'], agents: ['YOUR TEAM', '에이전트'],
  schedules: ['AUTOMATION', '예약 작업'], usage: ['OFFICE INTELLIGENCE', '오피스 대시보드'], settings: ['LOCAL CONFIG', '설정'],
  capabilities: ['CLI TOOLING', 'Code Agents'],
};
let state = { agents: [], cards: [], schedules: [], missions: [], settings: {}, presets: {roles:[],workflows:[],tasks:[]}, repository: {valid:false}, capabilities: {clients:[]}, github: null };
let page = 'workspace';
let workspaceTab = 'overview';
let selectedCapability = '';

function toast(message) {
  const el = $('#toast'); el.textContent = message; el.classList.add('show');
  clearTimeout(toast.timer); toast.timer = setTimeout(() => el.classList.remove('show'), 2600);
}
const agentOf = (id) => state.agents.find((a) => a.id === id);
const presetOf = (id) => state.presets.roles.find((preset) => preset.id === id);
const workflowOf = (id) => (state.presets.workflows||[]).find((workflow) => workflow.id === id);
const routingLabel = (project) => project?.routingMode==='manual'?'마스터 직접 처리':project?.routingMode==='sequential'?'지정 순서 실행':workflowOf(project?.workflowId)?.name||'작업 맞춤 자동 라우팅';
const projectOf = (id) => { const project=(state.settings.projects || []).find((item) => item.id === id); return project ? { routingMode:'adaptive', workflowId:'auto', ...project, agentIds: project.agentIds || [], pipeline: project.pipeline || [] } : null; };
const activeProject = () => projectOf(state.settings.activeProjectId) || (state.settings.projects || [])[0] || null;
const projectAgents = (project = activeProject()) => project ? (project.agentIds || []).map(agentOf).filter(Boolean) : [];
const visibleCards = () => activeProject() ? state.cards.filter((card) => card.projectId === activeProject().id || (!card.projectId && card.workdir === activeProject().path)) : [];
const cardsOf = (id) => state.cards.filter((c) => c.agentId === id);
const liveCard = (id) => cardsOf(id).find((c) => c.status === 'running') || cardsOf(id).find((c) => c.status === 'review');
const shortTime = (iso) => iso ? new Date(iso).toLocaleString('ko-KR', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';

async function load() {
  const [next,presets] = await Promise.all([api('/api/state'),api('/api/presets')]);
  state = { ...next, presets };
  const projectId=state.settings.activeProjectId||state.settings.projects?.[0]?.id||'';
  state.repository=await api('/api/repository?projectId='+encodeURIComponent(projectId)).catch(error=>({valid:false,error:error.message}));
  state.capabilities=state.repository.valid?await api('/api/capabilities?projectId='+encodeURIComponent(projectId)).catch(()=>({clients:[]})):{clients:[]};
  if(page==='workspace'&&projectId)state.github=await api('/api/github?projectId='+encodeURIComponent(projectId)).catch(error=>({error:error.message,issues:[],projects:[],pullRequests:[]}));
  if(!state.repository.valid&&!['workspace','settings'].includes(page))page='workspace';
  render();
}

async function navigate(next) {
  if($('.nav[data-page="'+next+'"]')?.classList.contains('requires-office')&&!state.repository.valid){toast('먼저 유효한 Git repo로 Office를 설정하세요.');next='workspace';}
  page = next; $$('.nav').forEach((b) => b.classList.toggle('active', b.dataset.page === page));
  [$('#eyebrow').textContent, $('#page-title').textContent] = viewInfo[page];
  $('#new-task').hidden = page === 'settings'||page==='workspace'||!state.repository.valid;
  if(page==='workspace'&&activeProject()){
    $('#page').innerHTML='<section class="panel"><div class="empty">Office와 Git 상태를 동기화하는 중…</div></section>';
    const projectId=activeProject()?.id||'';
    state.github=await api('/api/github?projectId='+encodeURIComponent(projectId)).catch(error=>({error:error.message,issues:[],projects:[]}));
    state.repository=await api('/api/repository?projectId='+encodeURIComponent(projectId)).catch(error=>({valid:false,error:error.message}));
  }
  render();
}

function stats() {
  return `<div class="stats"><div class="stat"><span>에이전트</span><b>${state.agents.length}</b></div><div class="stat"><span>실행/대기</span><b>${state.cards.filter(c=>c.status==='running'||c.status==='queued').length}</b></div><div class="stat"><span>검토 대기</span><b>${state.cards.filter(c=>c.status==='review').length}</b></div><div class="stat"><span>완료</span><b>${state.cards.filter(c=>c.status==='done').length}</b></div></div>`;
}

function render() {
  officeStage.unmount();
  renderSidebarRepo();
  renderNavigationState();
  const root = $('#page');
  if (page === 'workspace') root.innerHTML = workspaceView();
  if (page === 'office') root.innerHTML = officeView();
  if (page === 'board') root.innerHTML = boardView();
  if (page === 'history') root.innerHTML = historyView();
  if (page === 'agents') root.innerHTML = agentsView();
  if (page === 'schedules') root.innerHTML = officeSchedulesView();
  if (page === 'usage') root.innerHTML = usageView();
  if (page === 'capabilities') root.innerHTML = capabilitiesView();
  if (page === 'settings') root.innerHTML = settingsView();
  bindPage();
}

function renderNavigationState(){const ready=Boolean(state.repository?.valid);$$('.requires-office').forEach(button=>{button.disabled=!ready;button.title=ready?'':'먼저 Git repo Office를 설정하세요.';});$('#new-task').hidden=page==='settings'||page==='workspace'||!ready;$$('.nav').forEach(button=>button.classList.toggle('active',button.dataset.page===page));const info=viewInfo[page]||viewInfo.workspace;[$('#eyebrow').textContent,$('#page-title').textContent]=info;}

function renderSidebarRepo(){const box=$('#sidebar-repo'),project=activeProject(),valid=state.repository?.valid;if(!box)return;box.innerHTML=`<label>ACTIVE OFFICE</label><select aria-label="활성 Office">${(state.settings.projects||[]).map(p=>`<option value="${p.id}" ${p.id===project?.id?'selected':''}>${esc(p.name)}</option>`).join('')||'<option value="">Office 설정 필요</option>'}</select><button type="button" title="Office 설정">${project?'⚙':'＋'}</button><small class="${valid?'ready':'invalid'}">${valid?'● Git 연결됨':'○ 설정 필요'} · ${esc(project?.path||'로컬 Git repo를 연결하세요')}</small>`;const select=$('select',box);select?.addEventListener('change',async()=>{await api('/api/settings',{method:'PUT',body:{activeProjectId:select.value}});page='workspace';await load();});$('button',box)?.addEventListener('click',()=>openProject(project?.id));}

function officeView() {
  const project=activeProject(), agents=projectAgents(project), cards=visibleCards();
  const active=cards.filter(c=>c.status==='running'||c.status==='queued').length,review=cards.filter(c=>c.status==='review').length;
  const readiness=[
    {ok:Boolean(state.settings.defaultWorkdir||(state.settings.projects||[]).length),label:'작업 폴더'},
    {ok:Boolean(agents.length),label:'에이전트'},
    {ok:Boolean(agents.length&&agents.every(a=>a.presetId||a.systemPrompt)),label:'역할 지시'},
    {ok:Boolean(agents.length&&agents.every(agent=>state.settings.adapters?.[agent.adapter]?.executable)),label:'실행 어댑터'},
  ];
  const readyCount=readiness.filter(item=>item.ok).length;
  const shelf=(status,label)=>{const rows=cards.filter(c=>c.status===status).slice(0,6);return `<section class="office-shelf"><h3><span>${label}</span><b>${cards.filter(c=>c.status===status).length}</b></h3><div class="office-shelf-list">${rows.map(c=>`<button class="office-mini-card" data-card="${c.id}">${esc(c.title)}</button>`).join('')||'<div class="office-shelf-empty">비어 있음</div>'}</div></section>`;};
  const selector='';
  const missionRows=(state.missions||[]).filter(m=>!project||m.projectId===project.id).slice(0,5);
  return `<div class="office-dashboard">${selector}<section class="office-readiness"><div><b>시작 준비 ${readyCount}/4</b><span>${readyCount===4?'바로 작업을 맡길 수 있습니다.':'빠진 항목을 누르면 해당 설정으로 이동합니다.'}</span></div><div class="readiness-items">${readiness.map((item,i)=>`<button data-ready="${i}" class="${item.ok?'ok':''}">${item.ok?'✓':'○'} ${item.label}</button>`).join('')}</div></section><div class="office-statusbar"><div><h3>${esc(project?.name||'Local Agent Office')}</h3><p>${project?'repo 전담 멀티 에이전트 오피스':'repo를 고르면 전담 팀이 표시됩니다.'}</p></div><div class="office-live-summary"><span>배치 <b>${agents.length}</b></span><span>작업/대기 <b>${active}</b></span><span>검토 <b>${review}</b></span></div></div><div class="office-canvas-frame"><button class="office-add-agent" id="office-add-agent">＋ 에이전트 생성</button><canvas id="office-stage" aria-label="에이전트 가상 오피스"></canvas></div><div class="office-roster">${agents.map(a=>{const preset=presetOf(a.presetId);return `<button class="office-agent-chip" data-agent="${a.id}"><i style="background:${a.color}"></i><span><b>${esc(a.name)}</b><small>${esc(preset?.name||a.role||'역할 미지정')} · ${esc(a.modeId||preset?.modeId||'custom')}</small></span></button>`;}).join('')}</div><section class="office-launcher"><div class="launcher-main"><select id="office-agent">${project?.agentIds?.length?`<option value="__master__">★ 마스터에게 맡기기 · ${esc(routingLabel(project))}</option>`:''}${agents.map(a=>`<option value="${a.id}">${esc(a.name)} · ${esc(presetOf(a.presetId)?.name||a.role||a.adapter)}</option>`).join('')||'<option value="">배치된 에이전트가 필요합니다</option>'}</select><textarea id="office-prompt" placeholder="할 일을 적고 Enter로 바로 착수 · Shift+Enter 줄바꿈"></textarea><button class="launcher-settings" id="office-task-options" title="상세 작업 만들기">⚙</button><button class="primary" id="office-send" ${agents.length?'':'disabled'}>보내기</button></div><div class="launcher-hints"><span>${project?.executionMode==='isolated-worktrees'?'Worktree 격리 모드':'동일 repo 쓰기 직렬 보호'}</span><span>${esc(project?.path||state.settings.defaultWorkdir||'기본 작업 폴더')}</span><span>${esc(routingLabel(project))} · 고정 직무 순서 없음</span></div></section>${missionRows.length?`<section class="panel mission-strip"><h3>멀티 에이전트 미션</h3>${missionRows.map(m=>`<div><span class="status-pill ${m.status}">${esc(m.status)}</span><b>${esc(m.title)}</b><small>${esc(workflowOf(m.workflowId)?.name||m.workflowId||'직접')} · ${Math.min(m.stepIndex+1,m.pipeline.length)}/${m.pipeline.length} 단계</small></div>`).join('')}</section>`:''}<div class="office-shelves">${shelf('todo','TO-DO 선반')}${shelf('review','REVIEW 선반')}${shelf('done','DONE 선반')}</div></div>`;
}

const columns = [['todo','할 일'],['queued','대기열'],['running','작업 중'],['review','검토'],['done','완료']];
function boardView() {
  const cards=visibleCards(); return `<div class="board">${columns.map(([key,label]) => { const list=cards.filter(c=>c.status===key); return `<section class="column"><div class="column-head"><span>${label}</span><span class="count">${list.length}</span></div>${list.map(cardHtml).join('') || '<div class="empty" style="padding:35px 4px;font-size:11px">비어 있음</div>'}</section>`; }).join('')}</div>`;
}
function cardHtml(c) { const a=agentOf(c.agentId)||{name:'삭제된 에이전트',color:'#999'}; return `<article class="card" data-card="${c.id}"><h3>${esc(c.title)}</h3><div class="card-meta"><span class="mini-agent"><i style="background:${a.color}"></i>${esc(a.name)}</span><span>${shortTime(c.updatedAt)}</span></div></article>`; }

function historyView(){return `<section class="panel"><div class="row"><div class="field"><label>제목·지시·로그 검색</label><input id="history-query" placeholder="검색어를 입력하세요"></div><div class="field"><label>상태</label><select id="history-status"><option value="">전체</option>${columns.map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></div></div></section><div id="history-results" class="history-list">${historyResults('', '')}</div>`;}
function historyResults(query,status){const q=query.trim().toLowerCase();const rows=state.cards.filter(c=>(!status||c.status===status)&&(!q||`${c.title}\n${c.prompt}\n${c.output}\n${(c.followups||[]).map(f=>f.text).join('\n')}`.toLowerCase().includes(q)));return rows.map(c=>{const a=agentOf(c.agentId)||{};const snippet=(c.output||c.prompt||'').replace(/\s+/g,' ').slice(0,180);return `<article class="panel history-item" data-card="${c.id}"><div><span class="status-pill ${c.status}">${esc(c.status)}</span><h3>${esc(c.title)}</h3><p>${esc(snippet)}</p></div><div class="history-meta">${esc(a.name||'알 수 없음')}<br>${shortTime(c.updatedAt)}</div></article>`;}).join('')||'<div class="empty">일치하는 작업 기록이 없습니다.</div>';}

function projectsView(){const rows=state.settings.projects||[];return `<div class="settings"><section class="panel"><div style="display:flex;justify-content:space-between;align-items:center"><div><h3>Repo 오피스 관리</h3><p style="margin:0;color:var(--muted);font-size:11px">저장소마다 전담 팀, 작업 라우팅, 충돌 방지 방식을 설정합니다. 직무 순서는 고정되지 않습니다.</p></div><button class="primary" id="add-project">＋ Repo</button></div></section>${rows.map(raw=>{const p=projectOf(raw.id),names=(p.pipeline||[]).map(id=>agentOf(id)?.name).filter(Boolean);return `<section class="panel project-card"><div><h3>${esc(p.name)} ${p.id===activeProject()?.id?'<span class="role-badge assigned">현재 오피스</span>':''}</h3><p>${esc(p.description||'설명 없음')}</p><code>${esc(p.path)}</code><div class="repo-team">마스터: <b>${esc(agentOf(p.masterAgentId)?.name||'미지정')}</b> · 라우팅: <b>${esc(routingLabel(p))}</b>${p.routingMode==='sequential'?` · ${esc(names.join(' → ')||'순서 미설정')}`:''} · ${p.executionMode==='isolated-worktrees'?'worktree 격리':'동일 경로 직렬 보호'}</div></div><div class="actions"><button class="primary select-project" data-id="${p.id}">오피스 열기</button><button class="secondary edit-project" data-id="${p.id}">설정</button><button class="secondary task-project" data-path="${esc(p.path)}">단일 작업</button><button class="danger delete-project" data-id="${p.id}">삭제</button></div></section>`;}).join('')||'<div class="empty"><div class="big">▰</div><b>등록된 repo가 없습니다</b><p>Git 저장소를 등록하고 전담 팀을 배치하세요.</p></div>'}</div>`;}

const workspaceTabs=[['overview','개요'],['issues','Issues'],['kanban','Kanban'],['pulls','Pull Requests'],['branches','Branches'],['history','History'],['worktrees','Worktrees']];
function workspaceView(){
  const project=activeProject(),repo=state.repository||{},git=state.github||{issues:[],projects:[],pullRequests:[]},offices=state.settings.projects||[];
  if(!project)return `<div class="office-onboarding"><section class="panel onboarding-hero"><span>01</span><div><p class="eyebrow">START HERE</p><h2>로컬 Git repo로 첫 Office를 만드세요</h2><p>Office가 프로젝트의 최상위 단위입니다. 유효한 Git 저장소가 연결된 뒤 에이전트, 작업, 자동화와 Code Agent 설정이 활성화됩니다.</p><button class="primary" id="add-project">＋ Git repo 연결</button></div></section><div class="setup-flow"><article class="active"><b>1</b><span>Office</span><small>Git repo 연결</small></article><article><b>2</b><span>Code Agents</span><small>CLI와 도구 확인</small></article><article><b>3</b><span>Team</span><small>에이전트 배치</small></article><article><b>4</b><span>Work</span><small>Issue와 작업 실행</small></article></div></div>`;
  const summary=`<section class="panel repo-command"><div><span class="repo-state ${repo.valid?'ready':'invalid'}">${repo.valid?'● READY':'○ INVALID'}</span><h2>${esc(project.name)}</h2><code>${esc(project.path)}</code><p>${esc(project.description||'repo 전담 멀티 에이전트 Office')}</p></div><div class="repo-facts"><span><small>BRANCH</small><b>${esc(repo.branch||'-')}</b></span><span><small>CHANGES</small><b>${repo.changes?.length||0}</b></span><span><small>AGENTS</small><b>${projectAgents(project).length}</b></span><span><small>REMOTE</small><b>${git.slug?'GitHub':'Local'}</b></span></div><div class="actions"><button class="secondary" id="refresh-workspace">새로고침</button><button class="secondary" id="edit-office">Office 설정</button><button class="primary" id="add-project">＋ Office</button></div></section>`;
  const tabs=`<div class="workspace-tabs">${workspaceTabs.map(([id,label])=>`<button class="${workspaceTab===id?'active':''}" data-workspace-tab="${id}">${label}</button>`).join('')}</div>`;
  return `<div class="workspace-page">${summary}${repo.valid?'':`<div class="error-box"><b>이 Office는 활성화할 수 없습니다.</b><span>${esc(repo.error||'유효한 Git 저장소가 아닙니다.')}</span></div>`}${tabs}${workspaceTabView(project,repo,git,offices)}</div>`;
}

function workspaceTabView(project,repo,git,offices){
  if(workspaceTab==='overview')return `<div class="workspace-overview"><section class="panel hierarchy-panel"><div class="inventory-head"><div><h3>Office hierarchy</h3><p>Git repo가 모든 팀과 작업의 경계입니다.</p></div><span>${repo.valid?'연결 완료':'설정 필요'}</span></div><div class="hierarchy-tree"><div class="root"><b>▰ ${esc(project.name)}</b><small>${esc(repo.root||project.path)}</small></div><div><article><b>⌘ Code Agents</b><small>${state.capabilities?.clients?.length||0}개 CLI 프로필</small></article><article><b>◆ Team</b><small>${projectAgents(project).length}명 배치</small></article><article><b>▦ Work</b><small>${visibleCards().length}개 작업</small></article><article><b>◈ Git</b><small>${git.slug||'로컬 저장소'}</small></article></div></div></section><section class="panel office-list"><div class="inventory-head"><h3>등록된 Office</h3><span>${offices.length}개</span></div>${offices.map(item=>`<article class="${item.id===project.id?'active':''}"><div><b>${esc(item.name)}</b><small>${esc(item.path)}</small></div><button class="secondary select-project" data-id="${item.id}">${item.id===project.id?'열림':'열기'}</button></article>`).join('')}</section></div>`;
  if(workspaceTab==='issues')return `<section class="panel"><div class="inventory-head"><div><h3>GitHub Issues</h3><p>${git.authenticated?'요청을 Office 작업으로 가져올 수 있습니다.':'GitHub origin과 gh 인증이 필요합니다.'}</p></div><button class="primary" id="create-github-issue" ${git.authenticated?'':'disabled'}>＋ Issue</button></div>${git.error?`<div class="error-box">${esc(git.error)}</div>`:''}<div class="issue-list">${(git.issues||[]).map(issue=>`<article><span class="status-pill ${issue.state==='OPEN'?'running':'done'}">${esc(issue.state)}</span><div><b>#${issue.number} ${esc(issue.title)}</b><small>${shortTime(issue.updatedAt)} · ${(issue.labels||[]).map(label=>esc(label.name)).join(', ')||'label 없음'}</small></div><button class="secondary import-issue" data-number="${issue.number}">작업으로 가져오기</button></article>`).join('')||'<div class="empty">표시할 Issue가 없습니다.</div>'}</div></section>`;
  if(workspaceTab==='kanban')return `<section class="panel"><div class="inventory-head"><div><h3>GitHub Projects · Kanban</h3><p>Projects v2 필드와 항목을 읽기 전용으로 표시합니다.</p></div><span>${git.projects?.length||0}개</span></div>${git.projectError?`<div class="permission-box"><b>Projects 권한이 필요합니다</b><span>${esc(git.projectError)}</span><code>gh auth refresh -s read:project</code></div>`:''}<div class="kanban-projects">${(git.projects||[]).map(board=>`<article><header><b>▦ ${esc(board.title||`Project ${board.number}`)}</b><small>#${board.number} · ${(board.items||[]).length} items</small></header><div>${(board.items||[]).slice(0,30).map(item=>`<span><em>${esc(item.status||item.type||'No status')}</em><b>${esc(item.title||item.content?.title||'Untitled')}</b></span>`).join('')||'<small>표시할 항목이 없습니다.</small>'}</div></article>`).join('')||'<div class="empty">연결된 Project가 없습니다.</div>'}</div></section>`;
  if(workspaceTab==='pulls')return `<section class="panel"><div class="inventory-head"><h3>Pull Requests</h3><span>${git.pullRequests?.length||0}건</span></div><div class="git-rows">${(git.pullRequests||[]).map(pr=>`<a href="${esc(pr.url)}" target="_blank" rel="noreferrer"><span class="status-pill ${pr.state==='OPEN'?'running':'done'}">${pr.isDraft?'DRAFT':esc(pr.state)}</span><div><b>#${pr.number} ${esc(pr.title)}</b><small>${esc(pr.headRefName)} → ${esc(pr.baseRefName)} · ${shortTime(pr.updatedAt)}</small></div></a>`).join('')||'<div class="empty">Pull Request가 없습니다.</div>'}</div></section>`;
  if(workspaceTab==='branches')return `<section class="panel"><div class="inventory-head"><div><h3>Branches</h3><p>로컬과 remote branch를 최근 변경 순으로 표시합니다.</p></div><span>${repo.branches?.length||0}개</span></div><div class="git-rows">${(repo.branches||[]).map(branch=>`<article><span class="branch-icon">⑂</span><div><b>${esc(branch.name)} ${branch.current?'<em>current</em>':''}</b><small>${esc(branch.upstream||'upstream 없음')} · ${shortTime(branch.updatedAt)}</small></div></article>`).join('')}</div></section>`;
  if(workspaceTab==='history')return `<section class="panel"><div class="inventory-head"><div><h3>Commit History</h3><p>${esc(repo.branch||'현재 branch')} 최근 커밋</p></div><span>${repo.commits?.length||0}개</span></div><div class="commit-list">${(repo.commits||[]).map(commit=>`<article><code>${esc(commit.shortHash)}</code><div><b>${esc(commit.subject)}</b><small>${esc(commit.author)} · ${shortTime(commit.authoredAt)}</small></div></article>`).join('')}</div></section>`;
  return `<div class="worktree-layout"><section class="panel"><div class="inventory-head"><div><h3>Agent Worktrees</h3><p>격리 모드에서는 에이전트마다 전용 branch와 작업 폴더를 자동 준비합니다.</p></div><span>${repo.worktrees?.length||0}개</span></div><div class="git-rows">${(repo.worktrees||[]).map(tree=>`<article><span class="branch-icon">⌘</span><div><b>${esc(tree.branch||'detached')}</b><small>${esc(tree.path)}</small></div></article>`).join('')}</div></section><section class="panel"><h3>충돌 방지 상태</h3><p>${project.executionMode==='isolated-worktrees'?'에이전트별 worktree 격리가 활성화되어 있습니다.':'같은 repo 경로의 쓰기 작업을 직렬화합니다.'}</p>${repo.dirty?`<div class="warning-box"><b>기준 repo에 미커밋 변경 ${repo.changes.length}건</b><span>새 worktree에는 이 변경이 포함되지 않습니다.</span></div>`:'<div class="success-box">기준 repo가 깨끗합니다.</div>'}<div class="worktree-actions">${projectAgents(project).map(agent=>`<button class="secondary prepare-worktree" data-agent="${agent.id}" ${project.executionMode==='isolated-worktrees'?'':'disabled'}>${esc(agent.name)} 전용 worktree 준비</button>`).join('')||'<small>먼저 에이전트를 배치하세요.</small>'}</div></section></div>`;
}

function agentsView() {
  const agents=projectAgents();return `<section class="panel team-context"><div><span class="role-badge assigned">${esc(activeProject()?.name)}</span><h3>Office 전담 에이전트</h3><p>직함과 실행 모드를 분리했습니다. 한 FE 에이전트도 구현·UI·접근성 전문 태그를 함께 가질 수 있습니다.</p></div><button class="secondary" id="edit-office-team">팀·라우팅 관리</button></section><section class="panel"><h3>개발 오피스 모드 프리셋</h3><p>Roo Code류의 작업 모드 개념을 직함과 결합했습니다. 프리셋은 자동 라우팅에 쓰이는 모드와 전문 태그까지 설정합니다.</p><div class="preset-row">${state.presets.roles.map(r=>`<button class="preset-agent" data-preset="${r.id}"><i style="background:${r.color}"></i><b>${esc(r.name)}</b><span>${esc(r.role)}</span><em>${esc(r.modeId)} · ${(r.tags||[]).map(esc).join(' · ')}</em></button>`).join('')}</div></section><div class="agent-grid" style="margin-top:14px">${agents.map(a=>{const preset=presetOf(a.presetId),adapter=state.settings.adapters?.[a.adapter],mode=a.modeId||preset?.modeId||'custom';return `<article class="panel agent-card"><div class="agent-line"><div class="avatar" style="background:${a.color};color:${a.color}"><span style="color:#fff">${esc(a.name.slice(0,2).toUpperCase())}</span></div><div><b>${esc(a.name)}</b><small>${esc(adapter?.label||a.adapter)}${a.model?' · '+esc(a.model):''}</small></div></div><span class="role-badge ${preset?'assigned':'custom'}">${esc(mode)} · ${preset?esc(preset.name):'사용자 설정'}</span><p>${esc(a.role||'직함과 작업 모드를 지정하세요.')}</p><small>${esc((a.specialties||preset?.tags||[]).join(' · '))}</small><div class="actions"><button class="primary role-agent" data-id="${a.id}">${preset?'프리셋 변경':'프리셋 지정'}</button><button class="secondary edit-agent" data-id="${a.id}">세부 편집</button><button class="secondary task-agent" data-id="${a.id}">작업 맡기기</button><button class="danger delete-agent" data-id="${a.id}">삭제</button></div></article>`;}).join('')}<button class="panel agent-card" id="add-agent" style="border-style:dashed;cursor:pointer;min-height:180px;color:var(--muted);font-weight:800">＋ 이 Office에 에이전트 추가</button></div>`;
}

function schedulesView(){const rows=state.schedules||[],days=['일','월','화','수','목','금','토'];const label=s=>s.type==='interval'?`${s.intervalMinutes}분 간격`:s.type==='daily'?`매일 ${s.time}`:s.type==='weekly'?`매주 ${days[s.weekday]}요일 ${s.time}`:`1회 · ${shortTime(s.runAt)}`;return `<div class="settings"><section class="panel"><div style="display:flex;justify-content:space-between;align-items:center"><div><h3>자동 실행</h3><p style="margin:0;color:var(--muted);font-size:11px">한 번, 간격, 매일, 매주 규칙으로 작업 카드를 만듭니다.</p></div><button class="primary" id="add-schedule">＋ 예약</button></div></section>${rows.map(s=>`<section class="panel"><div style="display:flex;justify-content:space-between;gap:16px"><div><h3>${esc(s.name)}</h3><p>${label(s)} · 다음 ${s.nextRunAt?shortTime(s.nextRunAt):'없음'}${s.error?` · 오류: ${esc(s.error)}`:''}</p></div><div class="actions"><button class="secondary run-schedule" data-id="${s.id}">지금 실행</button><button class="danger delete-schedule" data-id="${s.id}">삭제</button></div></div></section>`).join('')||'<div class="empty"><div class="big">◷</div><b>예약 작업이 없습니다</b><p>반복 리포트나 정기 점검을 자동화할 수 있습니다.</p></div>'}</div>`;}

function usageView(){
  const project=activeProject(),cards=visibleCards(),staff=projectAgents(project),rows={},models={},daily={};
  let input=0,output=0,cached=0,duration=0,runs=0;const details=[];
  for(const c of cards){const agent=agentOf(c.agentId)||{},name=agent.name||'알 수 없음',model=agent.model||state.settings.adapters?.[agent.adapter]?.label||agent.adapter||'unknown';rows[name]||={input:0,output:0,duration:0,runs:0,model};models[model]||={input:0,output:0,runs:0};for(const run of [...(c.runs||[]),c]){if(!run.startedAt)continue;if(run.finishedAt){runs++;rows[name].runs++;models[model].runs++;}const d=Number(run.durationMs||0);duration+=d;rows[name].duration+=d;let ri=0,ro=0,rc=0;for(const e of run.events||[]){const u=e.data?.usage;if(u){ri+=Number(u.input_tokens||0);ro+=Number(u.output_tokens||0);rc+=Number(u.cached_input_tokens||0);}}const at=run.finishedAt||run.startedAt,date=String(at).slice(0,10);input+=ri;output+=ro;cached+=rc;rows[name].input+=ri;rows[name].output+=ro;models[model].input+=ri;models[model].output+=ro;daily[date]=(daily[date]||0)+ri+ro;details.push({title:c.title,agent:name,model,status:c.status,input:ri,output:ro,duration:d,at});}}
  const total=input+output,maxAgent=Math.max(1,...Object.values(rows).map(r=>r.input+r.output)),maxModel=Math.max(1,...Object.values(models).map(r=>r.input+r.output));
  const leader=Object.entries(rows).sort((a,b)=>(b[1].input+b[1].output)-(a[1].input+a[1].output))[0];
  const dates=[];for(let offset=83;offset>=0;offset--){const day=new Date();day.setHours(12,0,0,0);day.setDate(day.getDate()-offset);dates.push(day.toISOString().slice(0,10));}
  const heatMax=Math.max(1,...dates.map(date=>daily[date]||0));
  const recent=dates.slice(-14),recentMax=Math.max(1,...recent.map(date=>daily[date]||0));
  const heat=dates.map(date=>{const value=daily[date]||0,level=value?Math.max(1,Math.ceil(value/heatMax*4)):0;return `<i class="l${level}" title="${date} · ${value.toLocaleString()} tokens"></i>`;}).join('');
  return `<div class="office-dashboard-page"><section class="panel usage-filter"><div><span class="dashboard-kicker">LOCAL · PRIVATE</span><h3>${esc(project?.name||'전체')} 오피스 인텔리전스</h3><p>직원·세션·토큰 지출을 로컬 기록에서만 집계합니다. 통화 비용은 모델별 단가 설정 전까지 추정하지 않습니다.</p></div><select id="usage-repo"><option value="">전체 repo</option>${(state.settings.projects||[]).map(p=>`<option value="${p.id}" ${p.id===project?.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></section><div class="dashboard-stats"><article><span>오피스 직원</span><b>${staff.length}<small>명</small></b><em>${staff.filter(a=>cards.some(c=>c.agentId===a.id&&['running','queued'].includes(c.status))).length}명 근무 중</em></article><article><span>토큰 급여 · 지출량</span><b>${total.toLocaleString()}<small>tok</small></b><em>입력 ${input.toLocaleString()} · 출력 ${output.toLocaleString()}</em></article><article><span>완료 세션</span><b>${runs}<small>회</small></b><em>총 ${Math.round(duration/60000)}분 실행</em></article><article><span>이번 기간 MVP</span><b>${esc(leader?.[0]||'-')}</b><em>${leader?`${(leader[1].input+leader[1].output).toLocaleString()} tokens`:'실행 기록 없음'}</em></article></div><div class="dashboard-grid"><section class="panel activity-panel"><div class="inventory-head"><div><h3>84일 활동 히트맵</h3><p>GitHub 잔디처럼 실행 토큰이 기록된 날을 표시합니다.</p></div><span>${Object.values(daily).filter(Boolean).length} active days</span></div><div class="token-heatmap">${heat}</div><div class="heat-legend"><span>적음</span><i class="l0"></i><i class="l1"></i><i class="l2"></i><i class="l3"></i><i class="l4"></i><span>많음</span></div></section><section class="panel"><div class="inventory-head"><div><h3>최근 14일 토큰</h3><p>날짜별 입력+출력 합계</p></div><b>${total.toLocaleString()}</b></div><div class="daily-bars">${recent.map(date=>{const value=daily[date]||0;return `<span title="${date} · ${value.toLocaleString()} tokens"><i style="height:${Math.max(value?8:2,value/recentMax*100)}%"></i><small>${date.slice(5).replace('-','/')}</small></span>`;}).join('')}</div></section></div><div class="dashboard-grid"><section class="panel"><h3>직원별 토큰 급여 원장</h3>${Object.entries(rows).sort((a,b)=>(b[1].input+b[1].output)-(a[1].input+a[1].output)).map(([name,r],index)=>`<div class="usage-row ranked"><em>#${index+1}</em><span>${esc(name)}<small>${esc(r.model)} · ${r.runs}회 · ${Math.round(r.duration/60000)}분</small></span><div><i style="width:${Math.max(3,(r.input+r.output)/maxAgent*100)}%"></i></div><b>${(r.input+r.output).toLocaleString()} tok</b></div>`).join('')||'<div class="empty">아직 실행 기록이 없습니다.</div>'}</section><section class="panel"><h3>모델별 소비</h3>${Object.entries(models).sort((a,b)=>(b[1].input+b[1].output)-(a[1].input+a[1].output)).map(([name,r])=>`<div class="model-usage"><span><b>${esc(name)}</b><small>${r.runs} sessions</small></span><div><i style="width:${Math.max(3,(r.input+r.output)/maxModel*100)}%"></i></div><strong>${(r.input+r.output).toLocaleString()}</strong></div>`).join('')||'<div class="empty">모델 사용 기록이 없습니다.</div>'}</section></div><section class="panel"><div class="inventory-head"><div><h3>세션 원장</h3><p>최근 실행 50건</p></div><span>캐시 입력 ${cached.toLocaleString()}</span></div><div class="usage-table"><div class="usage-table-head"><span>작업</span><span>직원 / 모델</span><span>입력</span><span>출력</span><span>시간</span></div>${details.sort((a,b)=>String(b.at).localeCompare(String(a.at))).slice(0,50).map(r=>`<div><span>${esc(r.title)}<small>${shortTime(r.at)}</small></span><span>${esc(r.agent)}<small>${esc(r.model)}</small></span><span>${r.input.toLocaleString()}</span><span>${r.output.toLocaleString()}</span><span>${(r.duration/1000).toFixed(1)}s</span></div>`).join('')||'<div class="empty">상세 실행이 없습니다.</div>'}</div></section></div>`;
}

const capabilityLabels={runtime:'Runtime',mcp:'MCP',skills:'Skills',rules:'Rules / Instructions',plugins:'Plugins',subagents:'Subagents',agents:'Primary agents',commands:'Commands'};
function capabilitiesView(){const clients=state.capabilities?.clients||[];if(!clients.some(client=>client.id===selectedCapability))selectedCapability=clients[0]?.id||'';const selected=clients.find(client=>client.id===selectedCapability);const adapter=state.settings.adapters?.[selectedCapability];return `<div class="tooling-page"><section class="panel tooling-head"><div><h3>${esc(activeProject()?.name||'현재 repo')} Code Agents</h3><p>CLI 프로필을 선택하면 이 Office에 적용된 MCP·Skills·Rules·Plugins·Subagents를 확인할 수 있습니다.</p></div><div class="actions"><span>${shortTime(state.capabilities?.scannedAt)}</span><button class="primary" id="add-adapter">＋ 커스텀 프로필</button></div></section><div class="cli-grid selectable">${clients.map(client=>`<button class="panel cli-card ${client.id===selectedCapability?'selected':''}" data-capability="${esc(client.id)}"><div class="cli-title"><span class="cli-logo ${esc(client.family||client.id)}">${client.family==='opencode'?'OC':client.family==='claude'?'CL':client.family==='codex'?'CX':'LLM'}</span><div><h3>${esc(client.label)}</h3><p>${client.installed?'실행 파일 감지됨':'실행 파일 미감지'}</p></div><span class="status-pill ${client.installed?'done':'review'}">${client.installed?'READY':'SETUP'}</span></div><code>${esc(client.executable||'실행 파일 설정 필요')}</code><div class="cap-counts"><span><b>${client.counts?.mcp||0}</b>MCP</span><span><b>${client.counts?.skills||0}</b>Skills</span><span><b>${client.counts?.subagents||0}</b>Subagents</span></div></button>`).join('')}</div>${selected?`<section class="panel inventory"><div class="inventory-head"><div><h3>${esc(selected.label)} 적용 구성</h3><p>${esc(selected.family)} compatible · 비밀값과 프롬프트 본문은 표시하지 않습니다.</p></div><div class="actions">${adapter&&!adapter.builtIn&&!['codex','claude','opencode','custom'].includes(selected.id)?`<button class="secondary" id="edit-adapter">프로필 편집</button><button class="danger" id="delete-adapter">삭제</button>`:''}<span>global + project + profile</span></div></div>${Object.entries(capabilityLabels).map(([type,label])=>{const rows=(selected.items||[]).filter(item=>item.type===type);return rows.length?`<div class="inventory-group"><h4>${label} <b>${rows.length}</b></h4><div>${rows.map(item=>`<article><span class="scope ${item.scope}">${item.scope}</span><b>${esc(item.name)}</b>${item.mode?`<em>${esc(item.mode)}</em>`:''}${item.model?`<em>${esc(item.model)}</em>`:''}<small title="${esc(item.source)}">${esc(item.detail||item.source)}</small><i class="${item.enabled?'on':'off'}">${item.enabled?'적용':'비활성'}</i></article>`).join('')}</div></div>`:'';}).join('')||'<div class="empty">발견된 구성이 없습니다.</div>'}</section>`:'<div class="empty">CLI 프로필이 없습니다.</div>'}</div>`;}

function itoView(){const clients=state.capabilities?.clients||[],project=activeProject(),owners=projectAgents(project).filter(agent=>['claude','opencode'].includes(agent.adapter));const observed=visibleCards().flatMap(card=>(card.events||[]).filter(event=>event.type==='subagent.started').map(event=>({...event,card})));if(!owners.length&&!observed.length)return '';return `<section class="panel ito-office"><div class="inventory-head"><div><h3>ITO · 서브에이전트 인력풀</h3><p>Claude/OpenCode 담당자가 필요할 때 호출할 수 있는 격리된 전문 인력입니다.</p></div><span>${observed.filter(item=>item.card.status==='running').length}명 투입 중</span></div><div class="ito-grid">${owners.map(owner=>{const pool=clients.find(client=>client.id===owner.adapter)?.items?.filter(item=>item.type==='subagents'&&item.enabled)||[];return `<article class="ito-owner"><div class="agent-line"><i style="background:${owner.color}"></i><span><b>${esc(owner.name)}</b><small>${esc(owner.adapter)} 원청 담당</small></span></div><div class="ito-workers">${pool.slice(0,8).map(worker=>`<span><i>外</i><b>${esc(worker.name)}</b><small>${esc(worker.detail||worker.mode||'전문 subagent')}</small></span>`).join('')||'<em>등록된 서브에이전트 없음</em>'}</div></article>`;}).join('')}</div>${observed.length?`<div class="ito-observed"><b>최근 실제 호출</b>${observed.slice(-8).reverse().map(item=>`<span>${esc(agentOf(item.card.agentId)?.name||'Agent')} → ${esc(item.name)} · ${esc(item.card.title)}</span>`).join('')}</div>`:''}</section>`;}

function githubView(){const git=state.github||{issues:[],projects:[]},project=activeProject();return `<div class="git-page"><section class="panel git-head"><div><h3>${esc(git.slug||project?.name||'GitHub 연결')}</h3><p>${git.authenticated?'origin과 GitHub CLI 인증을 확인했습니다.':'repo의 GitHub origin과 gh 인증이 필요합니다.'}</p></div><div class="actions"><button class="secondary" id="refresh-github">새로고침</button><button class="primary" id="create-github-issue" ${git.authenticated?'':'disabled'}>＋ Issue</button></div></section>${git.error?`<div class="error-box">${esc(git.error)}</div>`:''}<div class="git-layout"><section class="panel"><div class="inventory-head"><h3>Issues</h3><span>${git.issues?.length||0}건</span></div><div class="issue-list">${(git.issues||[]).map(issue=>`<article><span class="status-pill ${issue.state==='OPEN'?'running':'done'}">${esc(issue.state)}</span><div><b>#${issue.number} ${esc(issue.title)}</b><small>${shortTime(issue.updatedAt)} · ${(issue.labels||[]).map(label=>esc(label.name)).join(', ')||'label 없음'}</small></div><button class="secondary import-issue" data-number="${issue.number}">작업으로 가져오기</button></article>`).join('')||'<div class="empty">Issue가 없거나 아직 동기화되지 않았습니다.</div>'}</div></section><section class="panel"><div class="inventory-head"><h3>Projects v2</h3><span>${git.projects?.length||0}개</span></div><div class="project-board-list">${(git.projects||[]).map(board=>`<article><span>▦</span><div><b>${esc(board.title||board.name||`Project ${board.number||''}`)}</b><small>#${board.number||'-'} · ${board.closed?'closed':'active'}</small></div></article>`).join('')||`<div class="empty">${git.projectError?'Projects 권한이 없거나 조회할 수 없습니다.':'연결된 Project가 없습니다.'}</div>`}</div></section></div></div>`;}

function settingsView() {
  const s=state.settings, a=s.adapters||{};
  const detected=s.detected||{};
  return `<div class="settings"><section class="panel"><h3>실행 환경</h3><p>모든 설정은 이 PC에만 저장됩니다. 마지막 자동 감지: ${detected.checkedAt?shortTime(detected.checkedAt):'아직 없음'}</p><div class="row"><div class="field"><label>동시 실행 수</label><input id="set-concurrency" type="number" min="1" max="8" value="${s.concurrency||2}"></div><div class="field"><label>기본 작업 폴더</label><div class="input-action"><input id="set-workdir" value="${esc(s.defaultWorkdir||'')}" placeholder="C:\\workspace"><button type="button" class="secondary" id="pick-default-folder">찾기</button></div></div></div></section><section class="panel"><h3>Windows 데스크톱</h3><p>앱 창을 닫으면 트레이에 유지됩니다.</p><div class="actions"><button class="secondary" id="toggle-autostart" disabled>자동 시작 확인 중…</button></div></section>${['codex','claude','opencode','custom'].map(k=>adapterPanel(k,a[k]||{})).join('')}<button class="primary" id="save-settings">설정 저장</button></div>`;
}
function adapterPanel(key,a){return `<section class="panel"><h3>${esc(a.label||key)} 어댑터</h3><p>명령은 셸을 통하지 않고 직접 실행됩니다.</p><div class="field"><label>실행 파일</label><input id="${key}-exe" value="${esc(a.executable||'')}" placeholder="${key}"></div><div class="field"><label>인자 · 한 줄에 하나</label><textarea id="${key}-args">${esc((a.args||[]).join('\n'))}</textarea><span class="hint">사용 가능: {prompt}, {workdir}, {model}</span></div></section>`;}

function bindPage() {
  if(page==='office'&&$('#office-stage'))officeStage.mount($('#office-stage'),projectAgents(),visibleCards(),id=>openAgent(id));
  if(page==='office'&&$('.office-shelves'))$('.office-shelves').insertAdjacentHTML('beforebegin',itoView());
  $('#office-repo')?.addEventListener('change',async(e)=>{await api('/api/settings',{method:'PUT',body:{activeProjectId:e.target.value}});await load();});
  $('#edit-active-repo')?.addEventListener('click',()=>openProject(activeProject()?.id));
  $$('.office-agent-chip').forEach(el=>el.onclick=()=>openAgent(el.dataset.agent));
  $$('.readiness-items button').forEach(el=>el.onclick=()=>{const target=Number(el.dataset.ready);if(target===0)navigate('workspace');else if(target===1||target===2)navigate('agents');else navigate('capabilities');});
  $$('.desk').forEach(el=>el.onclick=()=>openAgent(el.dataset.agent));
  $$('.office-mini-card').forEach(el=>el.onclick=()=>openCard(el.dataset.card));
  $('#office-add-agent')?.addEventListener('click',()=>openAgent());
  $('#office-task-options')?.addEventListener('click',()=>openTask($('#office-agent')?.value||''));
  const quickPrompt=$('#office-prompt');
  const sendQuick=async()=>{const prompt=quickPrompt?.value.trim(),agentId=$('#office-agent')?.value,project=activeProject();if(!prompt||!agentId)return;try{if(agentId==='__master__'){await api('/api/missions',{method:'POST',body:{title:prompt.split(/\r?\n/)[0].slice(0,64),prompt,projectId:project?.id}});}else{const card=await api('/api/cards',{method:'POST',body:{title:prompt.split(/\r?\n/)[0].slice(0,64),prompt,agentId,projectId:project?.id||'',workdir:project?.path||state.settings.defaultWorkdir||''}});await api(`/api/cards/${card.id}/run`,{method:'POST'});}quickPrompt.value='';await load();}catch(e){toast(e.message);}};
  $('#office-send')?.addEventListener('click',sendQuick);
  quickPrompt?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendQuick();}});
  $$('.card').forEach(el=>el.onclick=()=>openCard(el.dataset.card));
  $('#empty-agent')?.addEventListener('click',()=>openAgent()); $('#add-agent')?.addEventListener('click',()=>openAgent());
  $('#edit-office-team')?.addEventListener('click',()=>openProject(activeProject()?.id));
  $$('.preset-agent').forEach(el=>el.onclick=()=>openAgent('',el.dataset.preset));
  $$('.edit-agent').forEach(el=>el.onclick=()=>openAgent(el.dataset.id));
  $$('.role-agent').forEach(el=>el.onclick=()=>openRoleAssign(el.dataset.id));
  $$('.task-agent').forEach(el=>el.onclick=()=>openTask(el.dataset.id));
  $$('.delete-agent').forEach(el=>el.onclick=async()=>{if(confirm('이 에이전트를 삭제할까요?')){await act(()=>api('/api/agents/'+el.dataset.id,{method:'DELETE'}));await load();}});
  const historyQuery=$('#history-query'),historyStatus=$('#history-status');
  const filterHistory=()=>{const box=$('#history-results');if(!box)return;box.innerHTML=historyResults(historyQuery?.value||'',historyStatus?.value||'');$$('.history-item',box).forEach(el=>el.onclick=()=>openCard(el.dataset.card));};
  historyQuery?.addEventListener('input',filterHistory);historyStatus?.addEventListener('change',filterHistory);
  $('#add-project')?.addEventListener('click',()=>openProject());
  $$('.edit-project').forEach(el=>el.onclick=()=>openProject(el.dataset.id));
  $$('.select-project').forEach(el=>el.onclick=async()=>{await api('/api/settings',{method:'PUT',body:{activeProjectId:el.dataset.id}});workspaceTab='overview';page='workspace';await load();});
  $$('.task-project').forEach(el=>el.onclick=()=>openTask('',el.dataset.path));
  $$('.delete-project').forEach(el=>el.onclick=async()=>{if(confirm('이 프로젝트 프리셋을 삭제할까요?')){await act(()=>api('/api/projects/'+el.dataset.id,{method:'DELETE'}));await load();}});
  $('#add-schedule')?.addEventListener('click',openOfficeSchedule);
  $$('.run-schedule').forEach(el=>el.onclick=async()=>{await act(()=>api('/api/schedules/'+el.dataset.id+'/run',{method:'POST'}));toast('예약 작업을 실행 대기열에 추가했습니다.');await load();});
  $$('.delete-schedule').forEach(el=>el.onclick=async()=>{if(confirm('이 예약을 삭제할까요?')){await act(()=>api('/api/schedules/'+el.dataset.id,{method:'DELETE'}));await load();}});
  $('#save-settings')?.addEventListener('click',saveSettings);
  $('#refresh-workspace')?.addEventListener('click',()=>navigate('workspace'));
  $('#edit-office')?.addEventListener('click',()=>openProject(activeProject()?.id));
  $$('[data-workspace-tab]').forEach(el=>el.onclick=()=>{workspaceTab=el.dataset.workspaceTab;render();});
  $$('.prepare-worktree').forEach(el=>el.onclick=async()=>{try{el.disabled=true;el.textContent='준비 중…';const result=await api('/api/repository/worktrees',{method:'POST',body:{projectId:activeProject()?.id,agentId:el.dataset.agent}});toast(`${result.branch} worktree를 준비했습니다.`);await navigate('workspace');}catch(error){toast(error.message);el.disabled=false;}});
  $$('.cli-card[data-capability]').forEach(el=>el.onclick=()=>{selectedCapability=el.dataset.capability;render();});
  $('#add-adapter')?.addEventListener('click',()=>openAdapterProfile());
  $('#edit-adapter')?.addEventListener('click',()=>openAdapterProfile(selectedCapability));
  $('#delete-adapter')?.addEventListener('click',async()=>{if(!confirm('이 커스텀 CLI 프로필을 삭제할까요?'))return;try{await api('/api/adapters/'+encodeURIComponent(selectedCapability),{method:'DELETE'});selectedCapability='';await load();}catch(error){toast(error.message);}});
  $('#create-github-issue')?.addEventListener('click',openGithubIssue);
  if(page==='github'&&state.github?.projectError&&$('.project-board-list .empty'))$('.project-board-list .empty').innerHTML=`<b>Projects 권한이 필요합니다.</b><small>${esc(state.github.projectError)}</small>`;
  $$('.import-issue').forEach(el=>el.onclick=async()=>{const project=activeProject();try{await api('/api/github/import',{method:'POST',body:{projectId:project?.id,issueNumber:el.dataset.number,agentId:project?.masterAgentId||project?.agentIds?.[0]}});toast(`Issue #${el.dataset.number}를 작업으로 가져왔습니다.`);await load();navigate('board');}catch(error){toast(error.message);}});
  if ($('#usage-repo')?.options[0]?.value === '') $('#usage-repo').options[0].remove();
  $('#usage-repo')?.addEventListener('change',async(e)=>{await api('/api/settings',{method:'PUT',body:{activeProjectId:e.target.value}});await load();});
  $('#pick-default-folder')?.addEventListener('click',async()=>{try{const result=await api('/api/pick-folder',{method:'POST'});if(result.path)$('#set-workdir').value=result.path;}catch(e){toast(e.message);}});
  if($('#toggle-autostart'))loadDesktopSettings();
}

async function loadDesktopSettings(){const btn=$('#toggle-autostart');if(!btn)return;try{let current=await api('/api/desktop');if(!current.supported){btn.textContent='브라우저 모드에서는 자동 시작을 설정할 수 없습니다';return;}const paint=()=>{btn.disabled=false;btn.textContent=current.autostart?'✓ Windows 시작 시 자동 실행':'Windows 자동 시작 켜기';};paint();btn.onclick=async()=>{current=await api('/api/desktop/autostart',{method:'POST',body:{on:!current.autostart}});paint();toast(current.autostart?'자동 시작을 켰습니다.':'자동 시작을 껐습니다.');};}catch(e){btn.textContent=e.message;}}

function openGithubIssue(){const project=activeProject();if(!project)return;showModal('GITHUB ISSUE','새 Issue 만들기',`<div class="field"><label>제목</label><input id="gh-title" required placeholder="작업 목표를 한 줄로 적으세요"></div><div class="field"><label>본문</label><textarea id="gh-body" placeholder="배경, 범위, 완료 조건"></textarea></div><label class="check-row"><input id="gh-card" type="checkbox" checked> 마스터 에이전트 작업 카드도 함께 만들기</label><div class="actions"><button class="primary" type="submit">Issue 생성</button><button class="secondary" value="cancel">취소</button></div>`,async()=>{try{const issue=await api('/api/github/issues',{method:'POST',body:{projectId:project.id,title:$('#gh-title').value,body:$('#gh-body').value}});if($('#gh-card').checked){await api('/api/github/import',{method:'POST',body:{projectId:project.id,issueNumber:issue.number,agentId:project.masterAgentId||project.agentIds?.[0]}});}$('#modal').close();toast(`Issue #${issue.number}를 생성했습니다.`);workspaceTab='issues';page='workspace';await load();}catch(error){toast(error.message);}});}

function openProject(id=''){
  const p=projectOf(id)||{name:'',path:'',description:'',agentIds:[],masterAgentId:'',pipeline:[],executionMode:'shared-serial',routingMode:'adaptive',workflowId:'auto'};
  const workflowOptions=(state.presets.workflows||[]).map(w=>`<option value="${w.id}" ${p.workflowId===w.id?'selected':''}>${esc(w.name)} · ${esc(w.description)}</option>`).join('');
  showModal('REPO OFFICE',id?'Repo 팀 설정':'Repo 오피스 추가',`<div class="row"><div class="field"><label>Repo 이름</label><input id="project-name" value="${esc(p.name)}" placeholder="my-vibe-office"></div><div class="field"><label>충돌 방지 방식</label><select id="project-mode"><option value="shared-serial" ${p.executionMode!=='isolated-worktrees'?'selected':''}>동일 경로 쓰기 직렬 보호</option><option value="isolated-worktrees" ${p.executionMode==='isolated-worktrees'?'selected':''}>에이전트별 Git worktree</option></select></div></div><div class="field"><label>Git repo 폴더</label><div class="input-action"><input id="project-path" value="${esc(p.path)}" placeholder="C:\\workspace\\my-app"><button type="button" class="secondary" id="pick-project-folder">찾기</button></div></div><div class="field"><label>설명 / repo 규칙</label><input id="project-description" value="${esc(p.description)}" placeholder="프로젝트 용도, 금지 사항, 완료 기준"></div><div class="field"><label>이 repo에 배치할 에이전트</label><div class="agent-check-grid">${state.agents.map(a=>`<label><input type="checkbox" name="project-agent" value="${a.id}" ${p.agentIds.includes(a.id)?'checked':''}><i style="background:${a.color}"></i>${esc(a.name)} <small>${esc(a.modeId||a.role||a.adapter)}</small></label>`).join('')||'<span class="hint">먼저 에이전트를 생성하세요.</span>'}</div></div><div class="row"><div class="field"><label>마스터 에이전트</label><select id="project-master"><option value="">미지정</option>${state.agents.map(a=>`<option value="${a.id}" ${p.masterAgentId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label>작업 라우팅</label><select id="project-routing"><option value="adaptive" ${p.routingMode==='adaptive'?'selected':''}>작업 모드에 맞춰 자동 선택</option><option value="manual" ${p.routingMode==='manual'?'selected':''}>마스터가 직접 처리</option><option value="sequential" ${p.routingMode==='sequential'?'selected':''}>아래 지정 순서 실행</option></select></div></div><div class="row"><div class="field"><label>기본 워크플로</label><select id="project-workflow">${workflowOptions}</select><span class="hint">자동 라우팅에서도 특정 워크플로를 고정할 수 있습니다.</span></div><div class="field"><label>지정 순서 (선택 사항, Ctrl로 복수 선택)</label><select id="project-pipeline" multiple size="${Math.min(6,Math.max(3,state.agents.length))}">${state.agents.map(a=>`<option value="${a.id}" ${p.pipeline.includes(a.id)?'selected':''}>${esc(a.name)} · ${esc(a.modeId||a.role||a.adapter)}</option>`).join('')}</select></div></div><div class="prompt-guide"><b>가변 라우팅</b><span>PM→개발→디자인→QA 같은 고정 순서를 강제하지 않습니다. 자동 모드는 요청에 맞는 모드만 선택하고, 직접 모드는 마스터 한 명에게 맡기며, 지정 순서는 필요한 경우에만 사용합니다.</span></div><div class="actions"><button class="primary" type="submit">Repo 설정 저장</button><button class="secondary" value="cancel">취소</button></div>`,async()=>{const agentIds=$$('input[name="project-agent"]:checked').map(el=>el.value),pipeline=$$('#project-pipeline option:checked').map(el=>el.value);const saved=await api('/api/projects',{method:'POST',body:{id,name:$('#project-name').value,path:$('#project-path').value,description:$('#project-description').value,executionMode:$('#project-mode').value,routingMode:$('#project-routing').value,workflowId:$('#project-workflow').value,agentIds,masterAgentId:$('#project-master').value,pipeline}});await api('/api/settings',{method:'PUT',body:{activeProjectId:saved.id}});$('#modal').close();await load();});
  $('#project-master').onchange=()=>{const box=$(`input[name="project-agent"][value="${CSS.escape($('#project-master').value)}"]`);if(box)box.checked=true;};
  $('#pick-project-folder').onclick=async()=>{try{const result=await api('/api/pick-folder',{method:'POST'});if(result.path)$('#project-path').value=result.path;}catch(e){toast(e.message);}};
}

function openSchedule(){if(!state.agents.length){toast('먼저 에이전트를 만들어 주세요.');navigate('agents');return;}const next=new Date(Date.now()+3600000);next.setSeconds(0,0);const local=new Date(next.getTime()-next.getTimezoneOffset()*60000).toISOString().slice(0,16);const projects=state.settings.projects||[];showModal('AUTOMATION','예약 작업 만들기',`<div class="field"><label>이름</label><input id="sch-name" placeholder="매일 프로젝트 상태 점검"></div><div class="row"><div class="field"><label>에이전트</label><select id="sch-agent">${state.agents.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label>방식</label><select id="sch-type"><option value="once">한 번</option><option value="interval">반복 간격</option><option value="daily">매일</option><option value="weekly">매주</option></select></div></div><div class="row"><div class="field"><label>1회 실행 시각</label><input id="sch-at" type="datetime-local" value="${local}"></div><div class="field"><label>반복 간격(분)</label><input id="sch-interval" type="number" min="1" value="60"></div></div><div class="row"><div class="field"><label>매일/매주 시각</label><input id="sch-time" type="time" value="09:00"></div><div class="field"><label>요일</label><select id="sch-weekday">${['일','월','화','수','목','금','토'].map((d,i)=>`<option value="${i}" ${i===1?'selected':''}>${d}요일</option>`).join('')}</select></div></div><div class="field"><label>프로젝트</label><select id="sch-project"><option value="">기본 작업 폴더</option>${projects.map(p=>`<option value="${esc(p.path)}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>작업 폴더</label><input id="sch-workdir" value="${esc(state.settings.defaultWorkdir||'')}"></div><div class="field"><label>작업 지시</label><textarea id="sch-prompt" placeholder="정기적으로 수행할 작업과 완료 조건"></textarea></div><div class="actions"><button class="primary" type="submit">예약 저장</button><button class="secondary" value="cancel">취소</button></div>`,async()=>{await api('/api/schedules',{method:'POST',body:{name:$('#sch-name').value,agentId:$('#sch-agent').value,type:$('#sch-type').value,runAt:new Date($('#sch-at').value).toISOString(),intervalMinutes:$('#sch-interval').value,time:$('#sch-time').value,weekday:$('#sch-weekday').value,workdir:$('#sch-workdir').value,prompt:$('#sch-prompt').value}});$('#modal').close();await load();});$('#sch-project').onchange=()=>{if($('#sch-project').value)$('#sch-workdir').value=$('#sch-project').value;};}

function showModal(kicker,title,html,onSubmit) {
  $('#modal-kicker').textContent=kicker; $('#modal-title').textContent=title; $('#modal-body').innerHTML=html;
  const form=$('#modal-form'); form.onsubmit=async(e)=>{e.preventDefault();if(e.submitter?.value==='cancel'){$('#modal').close();return;}await onSubmit?.(e);};
  $$('[value="cancel"]',$('#modal-body')).forEach(button=>{button.type='button';button.onclick=()=>$('#modal').close();});
  $('#modal').showModal();
}

function openAgent(id,presetId='') {
  const preset=state.presets.roles.find(r=>r.id===presetId);
  const a=agentOf(id)||(preset?{name:preset.name,role:preset.role,modeId:preset.modeId,specialties:preset.tags,adapter:'codex',model:'',color:preset.color,systemPrompt:preset.prompt,presetId:preset.id}:{name:'',role:'',modeId:'custom',specialties:[],adapter:'codex',model:'',color:'#6958d9',systemPrompt:'',presetId:''});
  const selected=presetId||a.presetId||'';
  showModal('TEAM MEMBER',id?'에이전트 편집':'새 에이전트',`<div class="prompt-guide"><b>직함과 작업 모드</b><span>직함은 사람에게 보이는 책임이고, 작업 모드는 자동 라우터가 이 에이전트를 선택하는 실행 전문성입니다.</span></div><div class="field"><label>개발 오피스 프리셋</label><select id="a-preset"><option value="">사용자 직접 설정</option>${state.presets.roles.map(r=>`<option value="${r.id}" ${selected===r.id?'selected':''}>${esc(r.name)} · ${esc(r.modeId)} · ${esc(r.role)}</option>`).join('')}</select></div><div class="row"><div class="field"><label>이름</label><input id="a-name" value="${esc(a.name)}" required></div><div class="field"><label>직함 / 책임</label><input id="a-role" value="${esc(a.role)}" placeholder="프론트엔드 리드"></div></div><div class="row"><div class="field"><label>작업 모드</label><input id="a-mode" value="${esc(a.modeId||'custom')}" placeholder="frontend, debugger, architect"></div><div class="field"><label>전문 태그 (쉼표 구분)</label><input id="a-specialties" value="${esc((a.specialties||[]).join(', '))}" placeholder="react, accessibility, e2e"></div></div><div class="row"><div class="field"><label>어댑터</label><select id="a-adapter"></select></div><div class="field"><label>모델 (선택)</label><input id="a-model" value="${esc(a.model)}"></div></div><div class="field"><label>색상</label><input id="a-color" type="color" value="${a.color}"></div><div class="field"><label>기본 역할 지시</label><textarea id="a-prompt" placeholder="비워도 됩니다. 프리셋을 사용하면 자동으로 채워집니다.">${esc(a.systemPrompt)}</textarea><span class="hint">실행할 때 모든 작업 프롬프트 앞에 자동으로 결합됩니다.</span></div><div class="actions"><button class="primary" type="submit">${id?'변경 저장':'에이전트 생성'}</button><button class="secondary" value="cancel">취소</button></div>`,async()=>{await act(()=>api('/api/agents',{method:'POST',body:{id,name:$('#a-name').value,role:$('#a-role').value,modeId:$('#a-mode').value,specialties:$('#a-specialties').value.split(',').map(v=>v.trim()).filter(Boolean),adapter:$('#a-adapter').value,model:$('#a-model').value,color:$('#a-color').value,systemPrompt:$('#a-prompt').value,presetId:$('#a-preset').value}}));$('#modal').close();await load();});
  const adapterSelect=$('#a-adapter');adapterSelect.innerHTML=Object.entries(state.settings.adapters||{}).map(([key,profile])=>`<option value="${esc(key)}" ${a.adapter===key?'selected':''}>${esc(profile.label||key)}</option>`).join('');
  $('#a-preset').onchange=()=>{const role=presetOf($('#a-preset').value);if(!role)return;$('#a-role').value=role.role;$('#a-mode').value=role.modeId;$('#a-specialties').value=(role.tags||[]).join(', ');$('#a-color').value=role.color;$('#a-prompt').value=role.prompt;if(!id&&!$('#a-name').value.trim())$('#a-name').value=role.name;};
}

function openRoleAssign(id){
  const agent=agentOf(id);if(!agent)return;
  showModal('ROLE ASSIGNMENT',`${agent.name} 역할 지정`,`<div class="prompt-guide"><b>역할을 선택하면 무엇이 바뀌나요?</b><span>에이전트 이름과 CLI 연결은 유지하고, 역할 설명·기본 역할 지시·캐릭터 색상을 선택한 프리셋으로 교체합니다.</span></div><div class="role-choice-list">${state.presets.roles.map(r=>`<label class="role-choice"><input type="radio" name="role-choice" value="${r.id}" ${agent.presetId===r.id?'checked':''}><i style="background:${r.color}"></i><span><b>${esc(r.name)}</b><small>${esc(r.role)}</small><em>${esc(r.prompt)}</em></span></label>`).join('')}</div><label class="check-row"><input id="keep-agent-color" type="checkbox"> 현재 캐릭터 색상 유지</label><div class="actions"><button class="primary" type="submit">역할 적용</button><button class="secondary" value="cancel">취소</button></div>`,async()=>{const chosen=$('input[name="role-choice"]:checked');if(!chosen){toast('적용할 역할을 선택하세요.');return;}await api(`/api/agents/${id}/preset`,{method:'POST',body:{presetId:chosen.value,keepColor:$('#keep-agent-color').checked}});$('#modal').close();await load();toast(`${agent.name}에게 역할을 적용했습니다.`);});
}

function openTask(agentId='',presetWorkdir='') {
  const officeAgents=projectAgents(),project=activeProject();
  if(!state.repository.valid){toast('먼저 Git repo Office를 설정하세요.');navigate('workspace');return;}
  if(!officeAgents.length){toast('현재 Office에 에이전트를 배치해 주세요.');navigate('agents');return;}
  const s=state.settings, projects=s.projects||[], workdir=presetWorkdir||project.path;
  showModal('NEW ASSIGNMENT','새 작업',`<div class="prompt-guide"><b>이번 작업 상세 지시</b><span>목표·제약·완료 조건을 적으세요. 아래 템플릿을 선택하면 권장 구조를 자동으로 채웁니다.</span></div><div class="field"><label>작업 제목</label><input id="t-title" required placeholder="무엇을 맡길까요?"></div><div class="row"><div class="field"><label>에이전트</label><select id="t-agent">${state.agents.map(a=>`<option value="${a.id}" ${a.id===agentId?'selected':''}>${esc(a.name)} · ${esc(presetOf(a.presetId)?.name||a.role||a.adapter)}</option>`).join('')}</select></div><div class="field"><label>작업 템플릿</label><select id="t-template"><option value="">직접 작성</option>${state.presets.tasks.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div></div><div class="field"><label>프로젝트 프리셋</label><select id="t-project"><option value="">직접 지정</option>${projects.map(p=>`<option value="${esc(p.path)}" ${p.path===workdir?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>작업 폴더</label><div class="input-action"><input id="t-workdir" value="${esc(workdir)}" placeholder="에이전트가 작업할 폴더"><button type="button" class="secondary" id="pick-task-folder">찾기</button></div></div><div class="field"><label>상세 지시</label><textarea id="t-prompt" required placeholder="목표, 제약, 완료 조건을 적어주세요."></textarea></div><label class="check-row"><input id="t-run-now" type="checkbox" checked> 만든 뒤 바로 실행하기</label><div class="actions"><button class="primary" type="submit">작업 만들기</button><button class="secondary" value="cancel">취소</button></div>`,async()=>{const card=await act(()=>api('/api/cards',{method:'POST',body:{title:$('#t-title').value,agentId:$('#t-agent').value,workdir:$('#t-workdir').value,prompt:$('#t-prompt').value}}));const runNow=$('#t-run-now').checked;if(runNow){try{await api(`/api/cards/${card.id}/run`,{method:'POST'});}catch(e){toast(`작업은 저장했지만 실행하지 못했습니다: ${e.message}`);}}$('#modal').close();await load();navigate(runNow?'office':'board');});
  $('#t-agent').innerHTML=officeAgents.map(a=>`<option value="${a.id}" ${a.id===agentId?'selected':''}>${esc(a.name)} · ${esc(presetOf(a.presetId)?.name||a.role||a.adapter)}</option>`).join('');
  $('#t-project').value=project.path;$('#t-workdir').value=project.path;
  $('#t-template').onchange=()=>{const template=state.presets.tasks.find(t=>t.id===$('#t-template').value);if(template)$('#t-prompt').value=template.template;};
  $('#t-project').onchange=()=>{if($('#t-project').value)$('#t-workdir').value=$('#t-project').value;};
  $('#pick-task-folder').onclick=async()=>{try{const result=await api('/api/pick-folder',{method:'POST'});if(result.path)$('#t-workdir').value=result.path;}catch(e){toast(e.message);}};
}

function openCard(id) {
  const c=state.cards.find(x=>x.id===id); if(!c)return; const a=agentOf(c.agentId)||{};
  const busy=c.status==='running'||c.status==='queued';
  const controls=c.status==='todo'?`<button type="button" class="primary" data-act="run">▶ 실행</button>`:busy?`<button type="button" class="danger" data-act="stop">■ ${c.status==='queued'?'대기 취소':'중지'}</button>`:c.status==='review'?`<button type="button" class="primary" data-act="done">✓ 완료</button><button type="button" class="secondary" data-act="run">↻ 다시 실행</button>`:`<button type="button" class="secondary" data-act="move">할 일로 이동</button>`;
  const duration=c.durationMs!=null?` · ${(c.durationMs/1000).toFixed(1)}초`:'';
  showModal(esc(a.name||'AGENT'),c.title,`${c.error?`<div class="error-box">${esc(c.error)}</div>`:''}<div class="field"><label>작업 지시</label><div style="font-size:12px;line-height:1.6;white-space:pre-wrap">${esc(c.prompt)}</div><span class="hint">상태: ${esc(c.status)}${duration} · 이전 실행 ${(c.runs||[]).length}회${c.sessionId?' · 세션 '+esc(c.sessionId.slice(0,8)):''}</span></div><div class="field"><label>실행 로그</label><div class="log" id="card-log">${esc(c.output||'아직 실행 로그가 없습니다.')}</div></div>${c.status==='review'?`<div class="field"><label>후속 지시 후 같은 세션 계속</label><textarea id="followup-text" placeholder="수정하거나 추가로 확인할 내용을 입력하세요."></textarea></div>`:''}<div class="field"><label>이번 실행 산출물</label><div id="artifact-list" class="artifact-list">확인 중…</div><pre id="artifact-preview" class="log" hidden></pre></div><div class="actions">${controls}${c.status==='review'?'<button type="button" class="secondary" data-act="followup">＋ 후속 실행</button>':''}<button type="button" class="secondary" data-act="edit" ${busy?'disabled':''}>편집</button><button type="button" class="danger" data-act="delete" ${busy?'disabled':''}>삭제</button><button class="secondary" value="cancel">닫기</button></div>`,null);
  if(c.githubIssue){$('#modal-body').insertAdjacentHTML('afterbegin',`<div class="github-card-link"><a class="github-link" href="${esc(c.githubIssue.url)}" target="_blank" rel="noreferrer">◈ GitHub Issue #${c.githubIssue.number} · ${esc(c.githubIssue.title)}</a><button type="button" class="secondary" id="toggle-issue-state">${c.githubIssue.state==='OPEN'?'Issue 닫기':'Issue 다시 열기'}</button></div>`);$('#toggle-issue-state').onclick=async()=>{try{await api('/api/github/issues/state',{method:'POST',body:{projectId:c.projectId||activeProject()?.id,issueNumber:c.githubIssue.number,state:c.githubIssue.state==='OPEN'?'CLOSED':'OPEN'}});$('#modal').close();await load();toast('GitHub Issue 상태를 동기화했습니다.');}catch(error){toast(error.message);}};}
  loadArtifacts(id);
  $$('[data-act]',$('#modal-body')).forEach(b=>b.onclick=async()=>{const action=b.dataset.act;try{if(action==='edit'){openCardEdit(id);return;}if(action==='delete'&&!confirm('이 작업과 로그를 삭제할까요?'))return;if(action==='delete')await api('/api/cards/'+id,{method:'DELETE'});else if(action==='move')await api(`/api/cards/${id}/move`,{method:'POST',body:{status:'todo'}});else if(action==='followup')await api(`/api/cards/${id}/followup`,{method:'POST',body:{text:$('#followup-text').value}});else await api(`/api/cards/${id}/${action}`,{method:'POST'});$('#modal').close();await load();}catch(e){toast(e.message);}});
}

async function loadArtifacts(id){const box=$('#artifact-list');if(!box)return;try{const rows=await api('/api/artifacts?cardId='+encodeURIComponent(id));box.innerHTML=rows.length?rows.slice(0,30).map(f=>`<div><button type="button" class="artifact-file" data-path="${esc(f.path)}">${esc(f.path)}</button><span>${Math.max(1,Math.round(f.size/1024))} KB <button type="button" class="artifact-reveal" data-path="${esc(f.path)}" title="파일 위치 열기">↗</button></span></div>`).join(''):'변경된 파일이 없습니다.';$$('.artifact-file',box).forEach(btn=>btn.onclick=async()=>{const preview=$('#artifact-preview');try{const file=await api('/api/artifact?cardId='+encodeURIComponent(id)+'&path='+encodeURIComponent(btn.dataset.path));preview.hidden=false;preview.textContent=file.content;}catch(e){toast(e.message);}});$$('.artifact-reveal',box).forEach(btn=>btn.onclick=async()=>{try{await api('/api/artifact/open',{method:'POST',body:{cardId:id,path:btn.dataset.path}});}catch(e){toast(e.message);}});}catch(e){box.textContent=e.message;}}

function openCardEdit(id){const c=state.cards.find(x=>x.id===id);if(!c)return;showModal('EDIT TASK','작업 편집',`<div class="field"><label>제목</label><input id="edit-title" value="${esc(c.title)}"></div><div class="field"><label>작업 폴더</label><input id="edit-workdir" value="${esc(c.workdir||'')}"></div><div class="field"><label>작업 지시</label><textarea id="edit-prompt">${esc(c.prompt)}</textarea></div><div class="actions"><button class="primary" type="submit">저장</button><button class="secondary" value="cancel">취소</button></div>`,async()=>{await api('/api/cards/'+id,{method:'PUT',body:{title:$('#edit-title').value,workdir:$('#edit-workdir').value,prompt:$('#edit-prompt').value}});$('#modal').close();await load();});}

async function saveSettings(){const adapters={};for(const k of ['codex','claude','opencode','custom'])adapters[k]={executable:$(`#${k}-exe`).value,args:$(`#${k}-args`).value.split('\n').map(v=>v.trim()).filter(Boolean)};await act(()=>api('/api/settings',{method:'PUT',body:{concurrency:$('#set-concurrency').value,defaultWorkdir:$('#set-workdir').value,adapters}}));await load();toast('설정을 저장했습니다.');}
async function act(fn){try{return await fn();}catch(e){toast(e.message);throw e;}}

$$('.nav').forEach(b=>b.onclick=()=>navigate(b.dataset.page)); $('#new-task').onclick=()=>openTask();
$('#modal-close').onclick=()=>$('#modal').close();
const events=new EventSource('/api/events');
events.onopen=()=>{$('#server-dot').classList.add('ok');$('#server-label').textContent='서버 연결됨';};
events.onerror=()=>{$('#server-dot').classList.remove('ok');$('#server-label').textContent='재연결 중';};
events.addEventListener('card',async(e)=>{const card=JSON.parse(e.data);const i=state.cards.findIndex(c=>c.id===card.id);if(i>=0)state.cards[i]=card;else state.cards.unshift(card);render();if($('#card-log')&&card.output)$('#card-log').textContent=card.output;});
events.addEventListener('log',e=>{const d=JSON.parse(e.data),log=$('#card-log');if(log){log.textContent=(log.textContent==='아직 실행 로그가 없습니다.'?'':log.textContent)+d.text;log.scrollTop=log.scrollHeight;}});
events.addEventListener('mission',async()=>load());
events.addEventListener('reload',load);
load().catch(e=>toast(e.message));

function openAdapterProfile(id=''){const current=state.settings.adapters?.[id]||{label:'',family:'claude',executable:'claude',args:['-p','{prompt}'],env:{}};const editing=Boolean(id);showModal('CODE AGENT PROFILE',editing?'커스텀 CLI 프로필 편집':'커스텀 CLI 프로필 추가',`<div class="prompt-guide"><b>사내 LLM 라우팅도 프로필로 분리하세요</b><span>예: claude-samsung · Anthropic 호환 endpoint. 비밀키는 값 대신 <code>{env:COMPANY_LLM_TOKEN}</code>처럼 현재 PC의 환경 변수를 참조하는 방식을 권장합니다.</span></div><div class="row"><div class="field"><label>프로필 ID</label><input id="adapter-id" value="${esc(id)}" placeholder="claude-samsung" ${editing?'disabled':''}></div><div class="field"><label>표시 이름</label><input id="adapter-label" value="${esc(current.label)}" placeholder="Claude Samsung"></div></div><div class="row"><div class="field"><label>호환 계열</label><select id="adapter-family">${[['claude','Claude / Anthropic'],['codex','Codex'],['opencode','OpenCode'],['custom','Custom CLI']].map(([value,label])=>`<option value="${value}" ${current.family===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label>실행 파일</label><input id="adapter-exe" value="${esc(current.executable||'')}" placeholder="claude-samsung 또는 절대 경로"></div></div><div class="field"><label>인자 · 한 줄에 하나</label><textarea id="adapter-args">${esc((current.args||[]).join('\n'))}</textarea><span class="hint">사용 가능: {prompt}, {workdir}, {model}</span></div><div class="field"><label>환경 라우팅 · KEY=value</label><textarea id="adapter-env" placeholder="ANTHROPIC_BASE_URL=https://llm.company.local\nANTHROPIC_AUTH_TOKEN={env:COMPANY_LLM_TOKEN}">${esc(Object.entries(current.env||{}).map(([name,value])=>`${name}=${value}`).join('\n'))}</textarea><span class="hint">토큰 원문 대신 {env:변수명} 참조를 사용하세요.</span></div><div class="actions"><button class="primary" type="submit">프로필 저장</button><button class="secondary" value="cancel">취소</button></div>`,async()=>{const env={};for(const line of $('#adapter-env').value.split(/\r?\n/)){if(!line.trim())continue;const split=line.indexOf('=');if(split<1){toast(`환경 설정 형식 오류: ${line}`);return;}env[line.slice(0,split).trim()]=line.slice(split+1);}const saved=await api('/api/adapters',{method:'POST',body:{id:editing?id:$('#adapter-id').value,create:!editing,label:$('#adapter-label').value,family:$('#adapter-family').value,executable:$('#adapter-exe').value,args:$('#adapter-args').value.split(/\r?\n/).filter(Boolean),env}});selectedCapability=saved.id;$('#modal').close();await load();navigate('capabilities');});}

function openOfficeSchedule(){const agents=projectAgents(),project=activeProject();if(!agents.length){toast('현재 Office에 에이전트를 배치해 주세요.');navigate('agents');return;}const next=new Date(Date.now()+3600000);next.setSeconds(0,0);const local=new Date(next.getTime()-next.getTimezoneOffset()*60000).toISOString().slice(0,16);showModal('OFFICE AUTOMATION','예약 작업 만들기',`<div class="prompt-guide"><b>${esc(project.name)} 전용 자동화</b><span>이 예약은 현재 Git repo와 배치 에이전트 범위 안에서만 실행됩니다.</span></div><div class="field"><label>이름</label><input id="sch-name" placeholder="매일 프로젝트 상태 점검"></div><div class="row"><div class="field"><label>에이전트</label><select id="sch-agent">${agents.map(agent=>`<option value="${agent.id}">${esc(agent.name)}</option>`).join('')}</select></div><div class="field"><label>방식</label><select id="sch-type"><option value="once">한 번</option><option value="interval">반복 간격</option><option value="daily">매일</option><option value="weekly">매주</option></select></div></div><div class="row"><div class="field"><label>1회 실행 시각</label><input id="sch-at" type="datetime-local" value="${local}"></div><div class="field"><label>반복 간격(분)</label><input id="sch-interval" type="number" min="1" value="60"></div></div><div class="row"><div class="field"><label>매일/매주 시각</label><input id="sch-time" type="time" value="09:00"></div><div class="field"><label>요일</label><select id="sch-weekday">${['일','월','화','수','목','금','토'].map((day,index)=>`<option value="${index}" ${index===1?'selected':''}>${day}요일</option>`).join('')}</select></div></div><div class="field"><label>작업 지시</label><textarea id="sch-prompt" placeholder="정기적으로 수행할 작업과 완료 조건"></textarea></div><div class="actions"><button class="primary" type="submit">예약 저장</button><button class="secondary" value="cancel">취소</button></div>`,async()=>{await api('/api/schedules',{method:'POST',body:{name:$('#sch-name').value,agentId:$('#sch-agent').value,projectId:project.id,type:$('#sch-type').value,runAt:new Date($('#sch-at').value).toISOString(),intervalMinutes:$('#sch-interval').value,time:$('#sch-time').value,weekday:$('#sch-weekday').value,prompt:$('#sch-prompt').value}});$('#modal').close();await load();});}

function officeSchedulesView(){const project=activeProject(),rows=(state.schedules||[]).filter(schedule=>schedule.projectId===project?.id),days=['일','월','화','수','목','금','토'];const label=schedule=>schedule.type==='interval'?`${schedule.intervalMinutes}분 간격`:schedule.type==='daily'?`매일 ${schedule.time}`:schedule.type==='weekly'?`매주 ${days[schedule.weekday]}요일 ${schedule.time}`:`1회 · ${shortTime(schedule.runAt)}`;return `<div class="settings"><section class="panel team-context"><div><span class="role-badge assigned">${esc(project?.name)}</span><h3>Office 자동화</h3><p>예약 작업도 현재 repo와 전담 팀의 경계를 따릅니다.</p></div><button class="primary" id="add-schedule">＋ 예약</button></section>${rows.map(schedule=>`<section class="panel"><div style="display:flex;justify-content:space-between;gap:16px"><div><h3>${esc(schedule.name)}</h3><p>${label(schedule)} · 다음 ${schedule.nextRunAt?shortTime(schedule.nextRunAt):'없음'}${schedule.error?` · 오류: ${esc(schedule.error)}`:''}</p></div><div class="actions"><button class="secondary run-schedule" data-id="${schedule.id}">지금 실행</button><button class="danger delete-schedule" data-id="${schedule.id}">삭제</button></div></div></section>`).join('')||'<div class="empty"><div class="big">◷</div><b>이 Office의 예약 작업이 없습니다</b><p>반복 리포트나 정기 점검을 자동화할 수 있습니다.</p></div>'}</div>`;}
